System.register(["./jsx-runtime-legacy--q19JXeY.js","./index-legacy-gubfijRQ.js"],function(e,t){var a,s,o,n,r,i,h;return e("TermsPage",function(){const e=o(),t=h[n()];return(0,r.jsx)("div",{className:"min-h-screen bg-background px-4 py-10",children:(0,r.jsxs)("div",{className:"mx-auto max-w-2xl",children:[(0,r.jsxs)(s,{to:"/",className:"text-sm font-medium text-primary hover:underline",children:["← ",e("Басты бетке","На главную","Back home")]}),(0,r.jsx)("h1",{className:"mt-4 text-2xl font-bold text-foreground sm:text-3xl",children:t.title}),(0,r.jsx)("p",{className:"mt-1 text-sm text-muted-foreground",children:t.updated}),(0,r.jsx)("div",{className:"mt-8 space-y-6",children:t.sections.map(e=>(0,r.jsxs)("section",{children:[(0,r.jsx)("h2",{className:"text-base font-semibold text-foreground",children:e.h}),(0,r.jsx)("p",{className:"mt-1.5 text-sm leading-relaxed text-muted-foreground",children:e.p})]},e.h))}),(0,r.jsx)("p",{className:"mt-10 text-sm",children:(0,r.jsx)(s,{to:"/privacy",className:"font-medium text-primary hover:underline",children:e("Дербес деректерді өңдеу саясаты →","Политика обработки персональных данных →","Privacy Policy →")})})]})})}),{setters:[function(e){a=e.t},function(e){s=e.en,o=e.mt,n=e.pt}],execute:function(){r=a(),h={kk:{title:"Пайдалану шарттары",updated:"Соңғы жаңартылған күні: 2026 жылғы қазан",sections:[{h:"1. Жалпы ережелер",p:"Осы шарттар «Qazaq Teachers AI» платформасын (qazaqteachers.kz, бұдан әрі — Платформа) пайдалану тәртібін белгілейді. Тіркелу немесе Платформаны пайдалану арқылы сіз осы шарттармен және Дербес деректерді өңдеу саясатымен келісесіз. Келіспесеңіз, Платформаны пайдаланбаңыз."},{h:"2. Платформа не ұсынады",p:"Платформа мұғалімдерге арналған құралдар береді: AI көмегімен сабақ жоспарын (ҚМЖ), БЖБ/ТЖБ, презентация, жұмыс парағы және тест құрастыру, Qaz Quiz және басқа оқу ойындары, әдістемелік кабинет, курстар мен подкасттар. Оқушылар тек оқу ойындарын пайдаланады."},{h:"3. Есептік жазба",p:"Тіркелгенде шынайы мәлімет көрсетіңіз және құпиясөзіңізді ешкімге бермеңіз. Бір аккаунтты бір адам ғана пайдаланады; бір уақытта бір IP-ден ғана кіруге болады. Аккаунтыңызды профиль → «Қауіпсіздік» бөлімінде кез келген уақытта өзіңіз жоя аласыз."},{h:"4. AI жасаған материалдар",p:"AI жасаған материалдар — көмекші жоба. Оларда қате немесе дәлсіз мәлімет болуы мүмкін. Сабақта қолданбас бұрын мазмұнын тексеру мұғалімнің жауапкершілігінде. Платформаны күнделікті шектен тыс пайдалануды болдырмау үшін AI генерацияға күндік лимит қойылған."},{h:"5. Тыйым салынған әрекеттер",p:"Платформаны заңсыз мақсатта пайдалануға, басқа пайдаланушылардың деректеріне рұқсатсыз қол жеткізуге, жүйені бұзуға немесе шамадан тыс жүктеуге (бот, автоматты сұраныстар), ақылы мазмұнды көшіріп таратуға, басқаларды қорлайтын немесе жалған мазмұн жариялауға тыйым салынады. Бұзушылық болса, аккаунт ескертусіз бұғатталуы мүмкін."},{h:"6. Төлем және ақылы мазмұн",p:"Кейбір мазмұн (курстар, жазылым) ақылы болуы мүмкін. Бағалар теңгемен көрсетіледі. Төлем расталған соң қолжетімділік ашылады. Төлемді қайтару мәселелері Қазақстан Республикасының заңнамасына сәйкес төмендегі байланыс арқылы қаралады."},{h:"7. Зияткерлік меншік",p:"Платформаның дизайны, коды, логотипі және ортақ материалдары Платформаға тиесілі. Сіз жасаған материалдар (жоспарлар, тесттер, квиздер) сізге тиесілі; Платформа оларды тек сізге қызмет көрсету үшін сақтайды. Оқулық мазмұны авторлары мен баспаларының құқығында қалады."},{h:"8. Кәмелетке толмағандар",p:"18 жасқа толмаған оқушылар Платформаны ата-анасының немесе мұғалімінің келісімімен пайдаланады. Qaz Quiz-ге PIN арқылы қосылу үшін тіркелу қажет емес."},{h:"9. Жауапкершілікті шектеу",p:"Платформа «бар күйінде» ұсынылады. Біз үздіксіз жұмыс істеуіне тырысамыз, бірақ техникалық үзілістер, үшінші тарап қызметтерінің (хостинг, AI провайдерлер) ақаулары үшін жауап бермейміз. Маңызды материалдарыңыздың көшірмесін сақтап қойыңыз."},{h:"10. Шарттардың өзгеруі",p:"Шарттар жаңартылуы мүмкін. Жаңа нұсқа осы бетте жарияланған күннен бастап күшіне енеді. Платформаны пайдалануды жалғастыру — жаңа шарттармен келісу болып саналады."},{h:"11. Қолданылатын құқық және байланыс",p:"Осы шарттарға Қазақстан Республикасының заңнамасы қолданылады. Сұрақтар мен шағымдар бойынша: "+(i="nonamegold2024@gmail.com")}]},ru:{title:"Условия использования",updated:"Дата последнего обновления: октябрь 2026 года",sections:[{h:"1. Общие положения",p:"Настоящие условия определяют порядок использования платформы «Qazaq Teachers AI» (qazaqteachers.kz, далее — Платформа). Регистрируясь или пользуясь Платформой, вы соглашаетесь с этими условиями и Политикой обработки персональных данных. Если вы не согласны, не используйте Платформу."},{h:"2. Что предоставляет Платформа",p:"Платформа предоставляет учителям инструменты: создание с помощью AI поурочных планов (КСП), СОР/СОЧ, презентаций, рабочих листов и тестов, Qaz Quiz и другие обучающие игры, методический кабинет, курсы и подкасты. Ученики пользуются только обучающими играми."},{h:"3. Учётная запись",p:"При регистрации указывайте достоверные данные и никому не передавайте пароль. Одним аккаунтом пользуется один человек; одновременно вход возможен только с одного IP. Вы можете в любой момент сами удалить аккаунт в профиле → раздел «Безопасность»."},{h:"4. Материалы, созданные AI",p:"Материалы, созданные AI, — это вспомогательный черновик. В них возможны ошибки и неточности. Проверка содержания перед использованием на уроке — ответственность учителя. Чтобы предотвратить злоупотребления, для AI-генерации установлен дневной лимит."},{h:"5. Запрещённые действия",p:"Запрещается использовать Платформу в незаконных целях, получать несанкционированный доступ к данным других пользователей, взламывать или чрезмерно нагружать систему (боты, автоматические запросы), копировать и распространять платный контент, публиковать оскорбительный или ложный контент. При нарушении аккаунт может быть заблокирован без предупреждения."},{h:"6. Оплата и платный контент",p:"Часть контента (курсы, подписка) может быть платной. Цены указываются в тенге. Доступ открывается после подтверждения оплаты. Вопросы возврата рассматриваются в соответствии с законодательством Республики Казахстан через контакты ниже."},{h:"7. Интеллектуальная собственность",p:"Дизайн, код, логотип и общие материалы Платформы принадлежат Платформе. Созданные вами материалы (планы, тесты, квизы) принадлежат вам; Платформа хранит их только для оказания вам услуг. Содержание учебников остаётся правом их авторов и издательств."},{h:"8. Несовершеннолетние",p:"Ученики младше 18 лет пользуются Платформой с согласия родителей или учителя. Для входа в Qaz Quiz по PIN-коду регистрация не нужна."},{h:"9. Ограничение ответственности",p:"Платформа предоставляется «как есть». Мы стремимся к бесперебойной работе, но не отвечаем за технические перерывы и сбои сторонних сервисов (хостинг, AI-провайдеры). Сохраняйте копии важных материалов."},{h:"10. Изменение условий",p:"Условия могут обновляться. Новая редакция вступает в силу с момента публикации на этой странице. Продолжение использования Платформы означает согласие с новыми условиями."},{h:"11. Применимое право и контакты",p:`К настоящим условиям применяется законодательство Республики Казахстан. Вопросы и жалобы: ${i}`}]},en:{title:"Terms of Use",updated:"Last updated: October 2026",sections:[{h:"1. General",p:'These terms govern the use of the "Qazaq Teachers AI" platform (qazaqteachers.kz, the "Platform"). By registering or using the Platform you accept these terms and the Privacy Policy. If you do not agree, do not use the Platform.'},{h:"2. The service",p:"The Platform gives teachers AI tools for lesson plans, assessments, slides, worksheets and tests, Qaz Quiz and other learning games, a methodology cabinet, courses and podcasts. Students use only the learning games."},{h:"3. Account",p:"Provide accurate details and keep your password private. One account is for one person and may be active from one IP at a time. You can delete your account at any time in Profile → Security."},{h:"4. AI-generated content",p:"AI output is a draft and may contain errors. Teachers are responsible for reviewing it before use. AI generation has a daily limit to prevent abuse."},{h:"5. Prohibited use",p:"Illegal use, unauthorised access to other users' data, attacking or overloading the system, redistributing paid content, or posting abusive or false content is prohibited and may lead to account suspension."},{h:"6. Payments",p:"Some content may be paid; prices are in tenge. Access opens once payment is confirmed. Refunds are handled under the laws of the Republic of Kazakhstan via the contact below."},{h:"7. Intellectual property",p:"The Platform's design, code, logo and shared materials belong to the Platform. Content you create belongs to you and is stored only to serve you. Textbook content remains the property of its authors and publishers."},{h:"8. Minors",p:"Students under 18 use the Platform with a parent's or teacher's consent. Joining Qaz Quiz by PIN needs no account."},{h:"9. Liability",p:'The Platform is provided "as is". We are not liable for downtime or failures of third-party services (hosting, AI providers). Keep copies of important materials.'},{h:"10. Changes",p:"These terms may be updated; the new version applies from its publication on this page."},{h:"11. Law and contact",p:`These terms are governed by the laws of the Republic of Kazakhstan. Contact: ${i}`}]}}}}});